window.LESSON_WORDS={
  "媒体": {
    "meaning": "向公众传播信息的机构或渠道。",
    "en": "organisations or channels that communicate information to the public"
  },
  "糟糕": {
    "meaning": "情况很坏，令人不满意。",
    "en": "very bad or unsatisfactory"
  },
  "塑料": {
    "meaning": "一种常用的人造材料，课文介绍它的用途及废弃后的问题。",
    "en": "plastic; a common manufactured material"
  },
  "飞速": {
    "meaning": "非常迅速。",
    "en": "at great speed; very rapidly"
  },
  "产量": {
    "meaning": "一定时间内生产出来的数量。",
    "en": "the quantity produced during a period of time"
  },
  "几乎": {
    "meaning": "接近某种情况，但不表示完全如此。",
    "en": "almost; nearly but not completely"
  },
  "扮演": {
    "meaning": "文中指发挥某种作用。",
    "en": "here, play a particular role"
  },
  "一次性": {
    "meaning": "通常只使用一次。",
    "en": "single-use; normally used only once"
  },
  "廉价": {
    "meaning": "价钱便宜。",
    "en": "cheap; low in price"
  },
  "卫生": {
    "meaning": "清洁，符合健康方面的要求。",
    "en": "clean and meeting health standards"
  },
  "耐用": {
    "meaning": "经得起使用，不容易损坏。",
    "en": "durable; able to last through repeated use"
  },
  "风靡": {
    "meaning": "在一个时期或范围内非常流行。",
    "en": "become extremely popular"
  },
  "垄断": {
    "meaning": "独占，文中指塑料袋几乎占据整个超市购物袋市场。",
    "en": "dominate a market; here, plastic bags nearly take over supermarket bag use"
  },
  "消耗": {
    "meaning": "使用而逐渐耗去。",
    "en": "use up gradually"
  },
  "调查": {
    "meaning": "通过询问、观察等方法了解情况。",
    "en": "investigate by asking questions, observing or collecting information"
  },
  "至少": {
    "meaning": "表示数量的最低限度。",
    "en": "at least; the minimum amount"
  },
  "相当于": {
    "meaning": "在数量、程度或大小上大致对应。",
    "en": "be approximately equal to in amount, size or degree"
  },
  "丢弃": {
    "meaning": "扔掉，不再要。",
    "en": "throw away; discard"
  },
  "污染": {
    "meaning": "使环境等受到有害物质影响。",
    "en": "contaminate or damage the environment"
  },
  "降解": {
    "meaning": "材料逐渐分解的过程。",
    "en": "break down into simpler substances over time"
  },
  "填埋": {
    "meaning": "把垃圾等埋进地下。",
    "en": "bury waste in the ground"
  },
  "焚烧": {
    "meaning": "用火烧掉。",
    "en": "burn; incinerate"
  },
  "环保": {
    "meaning": "保护环境。",
    "en": "environmental protection"
  },
  "制品": {
    "meaning": "用某种材料制成的物品。",
    "en": "an item made from a particular material"
  },
  "将近": {
    "meaning": "接近某个数量或程度。",
    "en": "nearly; close to a given amount"
  },
  "再循环": {
    "meaning": "把废弃物回收处理后重新利用。",
    "en": "recycle; process waste so it can be used again"
  },
  "纷纷": {
    "meaning": "接连地，一个接一个地。",
    "en": "one after another; in large numbers"
  },
  "措施": {
    "meaning": "为解决问题而采取的办法。",
    "en": "a measure or step taken to solve a problem"
  },
  "遏制": {
    "meaning": "制止，控制。",
    "en": "curb; restrain or bring under control"
  },
  "征收": {
    "meaning": "依法收取税款或费用等。",
    "en": "levy or collect a tax or fee"
  },
  "消费者": {
    "meaning": "购买或使用商品、服务的人。",
    "en": "a consumer who buys or uses goods or services"
  },
  "多管齐下": {
    "meaning": "同时从多个方面采取办法。",
    "en": "tackle a problem in several ways at the same time"
  },
  "倡导": {
    "meaning": "提倡并带头推动。",
    "en": "promote and encourage a practice"
  },
  "逐渐": {
    "meaning": "慢慢地，一步步地。",
    "en": "gradually; step by step"
  },
  "机构": {
    "meaning": "办理某类事务的组织。",
    "en": "an organisation responsible for a type of work"
  },
  "奖励": {
    "meaning": "用一定方式鼓励某种行为或表现。",
    "en": "reward or encourage a desired action"
  },
  "自备": {
    "meaning": "自己准备。",
    "en": "bring or prepare one's own"
  },
  "问世": {
    "meaning": "新的事物出现。",
    "en": "appear or become available for the first time"
  },
  "便利": {
    "meaning": "方便。",
    "en": "convenience; making things easier"
  },
  "充斥": {
    "meaning": "充满，到处都是，常用于不好的事物。",
    "en": "be filled with something, usually undesirable"
  },
  "威胁": {
    "meaning": "可能造成危险或损害。",
    "en": "a threat; a possible source of harm"
  },
  "妥善": {
    "meaning": "稳妥而合适。",
    "en": "properly and appropriately"
  },
  "煞费苦心": {
    "meaning": "费尽心思。",
    "en": "take great pains and put much thought into something"
  },
  "不禁": {
    "meaning": "忍不住，不由自主。",
    "en": "cannot help doing or feeling something"
  },
  "吨": {
    "meaning": "计量质量的单位，一吨等于一千千克。",
    "en": "a tonne; 1,000 kilograms"
  },
  "烟尘": {
    "meaning": "燃烧产生的烟和细小颗粒。",
    "en": "smoke and fine particles produced by burning"
  },
  "土壤": {
    "meaning": "地面上能供植物生长的泥土。",
    "en": "soil in which plants can grow"
  },
  "吞食": {
    "meaning": "把食物或其他东西吞下去。",
    "en": "swallow food or other objects"
  },
  "消化道": {
    "meaning": "食物在身体内通过并被消化的通道。",
    "en": "the digestive tract through which food passes"
  },
  "堵塞": {
    "meaning": "被阻挡而不能畅通。",
    "en": "block or clog a passage"
  }
};
window.HWT_WORD_LEXICON=()=>window.LESSON_WORDS;
window.HWT_WORD_CONTEXT=()=>({lessonId:window.LESSON.id,grade:2,unit:3,lessonTitle:window.LESSON.title,paragraphs:window.LESSON.paragraphs,examplesMap:{"吨": {"text": "全球塑料产量（百万吨）", "label": "第二段折线图"}, "烟尘": {"text": "焚烧塑料垃圾产生的有害烟尘和有毒气体，会污染空气。", "label": "第五段危害示意图"}, "土壤": {"text": "塑料垃圾埋在地里200年也不一定能腐烂、降解，会严重污染土壤。", "label": "第五段危害示意图"}, "吞食": {"text": "河流和海洋里的塑料垃圾经常被动物当作食物吞食，导致动物因消化道堵塞而死亡。", "label": "第五段危害示意图"}, "消化道": {"text": "河流和海洋里的塑料垃圾经常被动物当作食物吞食，导致动物因消化道堵塞而死亡。", "label": "第五段危害示意图"}, "堵塞": {"text": "河流和海洋里的塑料垃圾经常被动物当作食物吞食，导致动物因消化道堵塞而死亡。", "label": "第五段危害示意图"}}});

/* Hosted assets are kept below the per-file size limit; the user gets one ZIP. */
(()=>{const button=document.querySelector('[data-pack=package]'),status=document.querySelector('#packStatus');
const hash=async data=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(x=>x.toString(16).padStart(2,'0')).join('');
async function download(manifest,button){button.disabled=true;let url;try{
 status.textContent='正在准备整套配套……';
 const response=await fetch('downloads/'+manifest);if(!response.ok)throw Error('清单暂时无法读取');const m=await response.json();
 const parts=[];let total=0;
 for(let i=0;i<m.parts.length;i++){const p=m.parts[i];status.textContent=`正在下载 ${i+1} / ${m.parts.length}，请稍候……`;const r=await fetch('downloads/'+p.file);if(!r.ok)throw Error('部分资源下载失败');const a=await r.arrayBuffer();if(a.byteLength!==p.bytes||await hash(a)!==p.sha256)throw Error('文件校验未通过，请重试');parts.push(a);total+=a.byteLength;}
 if(total!==m.bytes)throw Error('文件不完整');const blob=new Blob(parts,{type:m.mime||'application/zip'});if(await hash(await blob.arrayBuffer())!==m.sha256)throw Error('整套文件校验未通过');url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=m.name;document.body.appendChild(a);a.click();a.remove();status.textContent='文件已准备好，请在浏览器下载列表中保存。ZIP请先解压再使用。';setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch(e){status.textContent='下载未完成：'+e.message+'。可重试，或分别下载上方的PPT、教师方案和互动HTML。';if(url)URL.revokeObjectURL(url)}finally{button.disabled=false}}
button.onclick=()=>download('package-manifest.json',button);const offline=document.querySelector('[data-pack=offline]');offline.onclick=()=>download('offline-manifest.json',offline);
})();

[
  {
    "title": "人类最糟糕的发明",
    "notes": "导入：家里会留下多少塑料袋？买一次东西会用几个？听两三名学生回答，不另增书面任务。",
    "lesson": 1
  },
  {
    "title": "第一段：“得奖”为什么加引号？",
    "notes": "教参2.2：第一段引号题\n教师示范先比较词语通常含义与本段语境。先问后揭。",
    "lesson": 1
  },
  {
    "title": "“得奖”的特殊含义",
    "notes": "“得奖”通常是好事，但这里获评的是“最糟糕的发明”。引号表示特殊含义，带有反讽意味，突出这种发明产生的负面影响。\n不把引号一律解释成引用人物说话。",
    "lesson": 1
  },
  {
    "title": "第二段：结合图表读趋势",
    "notes": "课本第二段图表旁注；其余追问来自教参2.2\n在学习单点取与趋势对应的原句。",
    "lesson": 1
  },
  {
    "title": "全球塑料产量",
    "notes": "保留教材原图的曲线与绘图区，仅将坐标标签放大为可编辑文字。没有逐年原始数据，不制作虚假的精确年度序列。纵轴单位为百万吨，横轴为年份。局部下降可见。",
    "lesson": 1
  },
  {
    "title": "趋势概括要保留对象与范围",
    "notes": "从二十世纪五十年代开始，全球塑料产量整体上升很快。\n塑料不等于塑料袋，全球不等于我国。“几乎直线上升”不表示每年增加。",
    "lesson": 1
  },
  {
    "title": "第三段：为什么风靡全世界？",
    "notes": "教参2.2：塑料袋风靡题\n学生独立点选，不因数量醒目就把结果当原因。",
    "lesson": 1
  },
  {
    "title": "广泛流行的原因",
    "notes": "因为一次性塑料袋廉价、卫生、方便和耐用，适合人们购物等日常需要，所以很快在世界各地流行。\n四项信息均来自第三段。2011年每分钟100万个是课文历史资料。",
    "lesson": 1
  },
  {
    "title": "第四段：饼状图在说明什么？",
    "notes": "课本第四段旁注；图表信息追问来自教参2.2\n先读图表标题，再看类别及比例。",
    "lesson": 1
  },
  {
    "title": "每次上超市使用多少个塑料袋",
    "notes": "教材引自新加坡环境理事会。五类为0个15%、不去超市3%、1—2个33%、3—5个35%、6个或以上14%，合计100%。保留“不去超市”，不擅自重算分母。",
    "lesson": 1
  },
  {
    "title": "“至少3个”包括哪些人？",
    "notes": "饼状图说明的主要内容是什么？\n课文使用了饼状图中的哪些主要信息？除了这些主要信息，饼状图还提供了哪些信息？\n为什么要列举这些数字？\n提示最低界线是3，不是只取3—5那一类。",
    "lesson": 1
  },
  {
    "title": "用两类数据说明“大约一半”",
    "notes": "饼状图呈现受访者每次上超市使用塑料袋的数量类别及比例。课文选用3至5个占35%，并由35%加14%得出至少3个占49%，即大约一半。图中还显示0个占15%、不去超市占3%、1至2个占33%。这些数字具体说明人们使用塑料袋的情况，用量很大；8.2亿个及相当于126个滨海湾花园的比较，让庞大的用量更容易理解。\n其余资料：0个15%；不去超市3%；1—2个33%。",
    "lesson": 1
  },
  {
    "title": "为什么要列举这些数字？",
    "notes": "课本第四段旁注；图表信息追问来自教参2.2\n第一课独立写答：数字作用。可点取多句证据，写2—3句。",
    "lesson": 1
  },
  {
    "title": "从数量，解释到表达作用",
    "notes": "本题书面解释建议4分：用量大1分；引用适切数量或比例1分；指出用面积作比较1分；解释比较帮助理解庞大数量1分。各点独立给分。图表点选单独记录。\n第一课末核对和订正。不能只答“具体准确”。",
    "lesson": 1
  },
  {
    "title": "第二课：第五段的危害图",
    "notes": "课本第五段旁注；示意图作用题来自教参2.2\n先找不同去向，再配对后果。",
    "lesson": 2
  },
  {
    "title": "危害一：焚烧后的烟尘与毒气",
    "notes": "焚烧产生有害烟尘和有毒气体，会污染空气；填埋的塑料垃圾不易腐烂、降解，会严重污染土壤；进入河流和海洋的塑料垃圾会被动物当成食物吞食，导致消化道堵塞而死亡。示意图把不同去向和相应危害放在同一画面，配合文字，让读者更直观地理解。\n教材说明的是塑料垃圾焚烧产生的有害物质及其污染风险；不扩展成所有现代设施排放均未经处理。",
    "lesson": 2
  },
  {
    "title": "危害二：填埋后难以降解",
    "notes": "焚烧产生有害烟尘和有毒气体，会污染空气；填埋的塑料垃圾不易腐烂、降解，会严重污染土壤；进入河流和海洋的塑料垃圾会被动物当成食物吞食，导致消化道堵塞而死亡。示意图把不同去向和相应危害放在同一画面，配合文字，让读者更直观地理解。\n保留“也不一定”，不能推断满200年一定完全分解。",
    "lesson": 2
  },
  {
    "title": "危害三：动物误食",
    "notes": "焚烧产生有害烟尘和有毒气体，会污染空气；填埋的塑料垃圾不易腐烂、降解，会严重污染土壤；进入河流和海洋的塑料垃圾会被动物当成食物吞食，导致消化道堵塞而死亡。示意图把不同去向和相应危害放在同一画面，配合文字，让读者更直观地理解。\n动物将水中的塑料垃圾当作食物，误食导致消化道堵塞，可能死亡。依据是教材说明，不只看漫画推断。",
    "lesson": 2
  },
  {
    "title": "示意图为什么能帮助说明？",
    "notes": "你认为课文为什么要用示意图来说明塑料垃圾的危害？\n学生先口头解释，再揭下一页。",
    "lesson": 2
  },
  {
    "title": "图把去向和危害对应起来",
    "notes": "把“塑料垃圾去哪里”和“造成什么危害”对应起来，再说图怎样帮助理解。保留“200年也不一定能腐烂、降解”的限定，不能写成恰好200年便完全分解。\n这些关系同时呈现，使危害更直观。“生动形象”四字本身不是完整作用。",
    "lesson": 2
  },
  {
    "title": "第六段：怎样看出问题严重？",
    "notes": "课本第六段旁注及教参2.2\n第二课独立书面作答，允许累加两句原文。",
    "lesson": 2
  },
  {
    "title": "两句证据，各自说明什么？",
    "notes": "课文指出，我国每年使用17.6亿个塑料制品，其中将近一半是在超市使用的塑料袋，说明使用量庞大。2017年，这些塑料制品绝大部分最终成为垃圾，仅6%再循环使用，说明回收比例很低。因此，大量使用加上少量回收，造成严重的塑料垃圾问题。\n课文还有“将近一半是在超市使用的塑料袋”。保留限定。",
    "lesson": 2
  },
  {
    "title": "证据与结论之间的联系",
    "notes": "建议4分：17.6亿个及对象准确1分；说明用量大1分；2017年仅6%再循环或绝大部分成垃圾1分；解释大量使用而回收少造成垃圾多1分。各点独立给分。将近一半是可补充证据，不因漏答这一项清零。\n仅抄出数字可见定位；解释其意义才完成证据与判断的联系。",
    "lesson": 2
  },
  {
    "title": "6%的对象与年份",
    "notes": "只抄第一句评价；只写回收率低而漏掉庞大用量；把6%说成当前塑料袋回收率。\n不要把这一数字写成2026年塑料袋的回收率。此页用于答后纠错。",
    "lesson": 2
  },
  {
    "title": "第七段：其他国家的措施",
    "notes": "教师随段支架，为教参第八段比较题作准备\n这是第八段比较的随段支架，口头回答即可。",
    "lesson": 2
  },
  {
    "title": "减用与改变材料",
    "notes": "征收塑料袋税，让消费者付费购买塑料袋，不提供塑料袋；此外，使用可降解材料制造塑料袋，以减少环境污染。\n不把可降解理解为在任何环境都立即消失。",
    "lesson": 2
  },
  {
    "title": "第八段：本地做法有什么不同？",
    "notes": "课本第八段旁注及教参2.2\n让学生先点选，再口头说明比较理由。",
    "lesson": 2
  },
  {
    "title": "课文特别写出的本地做法",
    "notes": "课文特别指出，我国许多机构采用宣传、教育和奖励等方式，鼓励国人购物时自备购物袋。收费则是两段都提到的做法。\n“不同”只限课文信息，不推出别国没有宣传教育。",
    "lesson": 2
  },
  {
    "title": "第三课：第九段与开头的关系",
    "notes": "教参2.2结尾题；课本预习三\n先概括末段，再回看首段，不提前打乱逐段阅读。",
    "lesson": 3
  },
